from collections import defaultdict, deque
R,C=len(grid),len(grid[0]); seen=set(); comps=[]
for r in range(R):
 for c in range(C):
  col=grid[r][c]
  if col==4 or (r,c) in seen: continue
  q=[(r,c)];seen.add((r,c)); comp=[]
  while q:
   a,b=q.pop();comp.append((a,b))
   for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
    x,y=a+da,b+db
    if 0<=x<R and 0<=y<C and grid[x][y]==col and (x,y) not in seen:
     seen.add((x,y));q.append((x,y))
  comps.append((col,comp))
def sig(cells):
 r0=min(r for r,c in cells);c0=min(c for r,c in cells)
 return tuple(sorted((r-r0,c-c0) for r,c in cells))
for col, cells in comps:
 print(col,len(cells),(min(r for r,c in cells),min(c for r,c in cells)),(max(r for r,c in cells),max(c for r,c in cells)),sig(cells))

